insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930011','40000000-0000-4000-8000-000000993001','A potência envolve uma função quadrática cuja derivada aparece fora dos parênteses.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930012','40000000-0000-4000-8000-000000993001','Defina $u=2x^2+3$ e converta também os limites.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930013','40000000-0000-4000-8000-000000993001','Confira que $u$ percorre o intervalo de $3$ a $5$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993001','$272$','A expressão interna relevante é $2x^2+3$. Com $u=2x^2+3$, temos $du=4x\,dx$, portanto $8x\,dx=2\,du$. Os extremos $x=0$ e $x=1$ tornam-se $u=3$ e $u=5$. A integral passa a ser $2\int_3^5u^3du=[u^4/2]_3^5=(625-81)/2=272$. O resultado é positivo e maior que a largura do intervalo vezes o mínimo do integrando; a alternativa C é coerente.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930011','40000000-0000-4000-8000-000000993001','A expressão interna relevante é $2x^2+3$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930012','40000000-0000-4000-8000-000000993001','Com $u=2x^2+3$, temos $du=4x\,dx$, portanto $8x\,dx=2\,du$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930013','40000000-0000-4000-8000-000000993001','Os extremos $x=0$ e $x=1$ tornam-se $u=3$ e $u=5$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930014','40000000-0000-4000-8000-000000993001','A integral passa a ser $2\int_3^5u^3du=[u^4/2]_3^5=(625-81)/2=272$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930015','40000000-0000-4000-8000-000000993001','O resultado é positivo e maior que a largura do intervalo vezes o mínimo do integrando; a alternativa C é coerente.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993002','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','easy','published','Uma partícula tem velocidade $v(t)=6t-4$ metros por segundo. Qual é seu deslocamento entre $t=1$ e $t=3$ segundos?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
