insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930021','40000000-0000-4000-8000-000000993002','Deslocamento é a integral da velocidade, com sinal, no intervalo de tempo.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930022','40000000-0000-4000-8000-000000993002','Encontre uma primitiva de $6t-4$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930023','40000000-0000-4000-8000-000000993002','Compare os valores de $3t^2-4t$ em $t=3$ e $t=1$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993002','$16$ m','O deslocamento é $\int_1^3(6t-4)\,dt$. Uma primitiva da velocidade é $3t^2-4t$. No instante final, ela vale $27-12=15$. No instante inicial, vale $3-4=-1$; a diferença é $15-(-1)=16$. A unidade é metro e o valor corresponde à alternativa D.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930021','40000000-0000-4000-8000-000000993002','O deslocamento é $\int_1^3(6t-4)\,dt$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930022','40000000-0000-4000-8000-000000993002','Uma primitiva da velocidade é $3t^2-4t$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930023','40000000-0000-4000-8000-000000993002','No instante final, ela vale $27-12=15$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930024','40000000-0000-4000-8000-000000993002','No instante inicial, vale $3-4=-1$; a diferença é $15-(-1)=16$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
