insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993003','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','easy','published','Se $A(x)=\int_2^{x^2}(1+t^3)\,dt$ para $x>0$, qual é $A\prime(1)$?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
