insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930031','40000000-0000-4000-8000-000000993003','A','$2$',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930032','40000000-0000-4000-8000-000000993003','B','$4$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930033','40000000-0000-4000-8000-000000993003','C','$6$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930034','40000000-0000-4000-8000-000000993003','D','$8$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('40000000-0000-4000-8000-000000993003','50000000-0000-4000-8000-000009930032') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930031','40000000-0000-4000-8000-000000993003','O limite superior é uma função de $x$, então há uma regra da cadeia após o Teorema Fundamental.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930032','40000000-0000-4000-8000-000000993003','Avalie o integrando em $t=x^2$ e multiplique pela derivada de $x^2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930033','40000000-0000-4000-8000-000000993003','Antes de substituir $x=1$, verifique que $A\prime(x)=(1+x^6)2x$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993003','$4$','Escreva $f(t)=1+t^3$ e $g(x)=x^2$. Para $\int_2^{g(x)}f(t)dt$, a derivada é $f(g(x))g\prime(x)$. Assim, $A\prime(x)=(1+(x^2)^3)2x=2x(1+x^6)$. Em $x=1$, obtemos $2(1)(2)=4$. O limite inferior constante não contribui; a resposta é B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930031','40000000-0000-4000-8000-000000993003','Escreva $f(t)=1+t^3$ e $g(x)=x^2$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930032','40000000-0000-4000-8000-000000993003','Para $\int_2^{g(x)}f(t)dt$, a derivada é $f(g(x))g\prime(x)$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930033','40000000-0000-4000-8000-000000993003','Assim, $A\prime(x)=(1+(x^2)^3)2x=2x(1+x^6)$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930034','40000000-0000-4000-8000-000000993003','Em $x=1$, obtemos $2(1)(2)=4$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930035','40000000-0000-4000-8000-000000993003','O limite inferior constante não contribui; a resposta é B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993004','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','easy','published','Qual é uma primitiva de $3x^2\ln 5$?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
