insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930041','40000000-0000-4000-8000-000000993004','A','$x^3\ln5+C$',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930042','40000000-0000-4000-8000-000000993004','B','$3x^3\ln5+C$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930043','40000000-0000-4000-8000-000000993004','C','$x^3/(3\ln5)+C$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930044','40000000-0000-4000-8000-000000993004','D','$x^2\ln5+C$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('40000000-0000-4000-8000-000000993004','50000000-0000-4000-8000-000009930041') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930041','40000000-0000-4000-8000-000000993004','Apesar da presença de um logaritmo, $\ln5$ é apenas uma constante.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930042','40000000-0000-4000-8000-000000993004','Retire o fator constante e aplique a regra da potência a $x^2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930043','40000000-0000-4000-8000-000000993004','Derive $x^3\ln5$ para conferir o coeficiente.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993004','$x^3\ln5+C$','O número $\ln5$ não depende de $x$. Logo $\int3x^2\ln5\,dx=\ln5\int3x^2dx$. Pela regra da potência, $\int3x^2dx=x^3$. A família de primitivas é $x^3\ln5+C$. Sua derivada é exatamente $3x^2\ln5$, confirmando A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930041','40000000-0000-4000-8000-000000993004','O número $\ln5$ não depende de $x$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930042','40000000-0000-4000-8000-000000993004','Logo $\int3x^2\ln5\,dx=\ln5\int3x^2dx$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930043','40000000-0000-4000-8000-000000993004','Pela regra da potência, $\int3x^2dx=x^3$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930044','40000000-0000-4000-8000-000000993004','A família de primitivas é $x^3\ln5+C$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930045','40000000-0000-4000-8000-000000993004','Sua derivada é exatamente $3x^2\ln5$, confirmando A.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993005','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','easy','published','Uma bola quica atingindo, a cada salto, $60\%$ da altura anterior. Se o primeiro salto alcança $5$ m, qual é a soma das alturas máximas de todos os saltos?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
