insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993005','$12,5$ m','A sequência de alturas é $5,3,1,8,\ldots$. Ela é geométrica com $a=5$ e $r=0,6$. Como $|r|<1$, a soma infinita existe. Calculamos $S=5/(1-0,6)=5/0,4=12,5$. A unidade permanece metro e a alternativa C responde apenas às alturas máximas.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930051','40000000-0000-4000-8000-000000993005','A sequência de alturas é $5,3,1,8,\ldots$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
