insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930053','40000000-0000-4000-8000-000000993005','Como $|r|<1$, a soma infinita existe.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930054','40000000-0000-4000-8000-000000993005','Calculamos $S=5/(1-0,6)=5/0,4=12,5$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
