insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930063','40000000-0000-4000-8000-000000993006','C','$3/5$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930064','40000000-0000-4000-8000-000000993006','D','$4/5$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
