insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930062','40000000-0000-4000-8000-000000993006','Divida numerador e denominador por $n$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930063','40000000-0000-4000-8000-000000993006','Preserve o sinal do coeficiente dominante do numerador.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993006','$-3/5$','Reescrevemos $a_n=(4/n-3)/(5+2/n)$. Quando $n\to\infty$, os termos $4/n$ e $2/n$ tendem a zero. O numerador tende a $-3$ e o denominador tende a $5$. Portanto $a_n\to-3/5$. O sinal negativo elimina as alternativas C e D; a correta é B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930061','40000000-0000-4000-8000-000000993006','Reescrevemos $a_n=(4/n-3)/(5+2/n)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930062','40000000-0000-4000-8000-000000993006','Quando $n\to\infty$, os termos $4/n$ e $2/n$ tendem a zero.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930063','40000000-0000-4000-8000-000000993006','O numerador tende a $-3$ e o denominador tende a $5$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930064','40000000-0000-4000-8000-000000993006','Portanto $a_n\to-3/5$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930065','40000000-0000-4000-8000-000000993006','O sinal negativo elimina as alternativas C e D; a correta é B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993007','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','easy','published','Para qual valor de $p$ a integral $\int_1^\infty x^{-p}\,dx$ certamente converge?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
