insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930071','40000000-0000-4000-8000-000000993007','Recorde o critério da integral do tipo $p$ no intervalo infinito.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930072','40000000-0000-4000-8000-000000993007','O caso-limite $p=1$ produz um logaritmo sem limite finito.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930073','40000000-0000-4000-8000-000000993007','A convergência ocorre somente quando o expoente no denominador supera $1$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993007','$p=3$','A integral pode ser escrita como $\int_1^\infty1/x^p\,dx$. O critério para essa família é convergência exatamente quando $p>1$. Os valores $-2$ e $0$ nem sequer fazem o integrando decair. O valor $1$ é o caso harmônico divergente, enquanto $3>1$. Logo somente a alternativa D garante convergência.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930071','40000000-0000-4000-8000-000000993007','A integral pode ser escrita como $\int_1^\infty1/x^p\,dx$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930072','40000000-0000-4000-8000-000000993007','O critério para essa família é convergência exatamente quando $p>1$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930073','40000000-0000-4000-8000-000000993007','Os valores $-2$ e $0$ nem sequer fazem o integrando decair.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930074','40000000-0000-4000-8000-000000993007','O valor $1$ é o caso harmônico divergente, enquanto $3>1$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930075','40000000-0000-4000-8000-000000993007','Logo somente a alternativa D garante convergência.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
