insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930081','40000000-0000-4000-8000-000000993008','Uma série geométrica tem razão constante entre termos consecutivos.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930082','40000000-0000-4000-8000-000000993008','Depois de reconhecer a forma, confira se o módulo da razão é menor que $1$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930083','40000000-0000-4000-8000-000000993008','Uma p-série convergente não se torna geométrica apenas por também convergir.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993008','$\sum_{n=0}^\infty(-2/3)^n$','A alternativa A é geométrica, mas sua razão tem módulo $5/4>1$. As alternativas B e D são p-séries, pois o índice aparece como potência no denominador. Na alternativa C, cada termo é o anterior multiplicado por $-2/3$. Como $|-2/3|<1$, essa série geométrica converge. Assim, C é a única opção que satisfaz as duas condições.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930081','40000000-0000-4000-8000-000000993008','A alternativa A é geométrica, mas sua razão tem módulo $5/4>1$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
