insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930083','40000000-0000-4000-8000-000000993008','Na alternativa C, cada termo é o anterior multiplicado por $-2/3$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930084','40000000-0000-4000-8000-000000993008','Como $|-2/3|<1$, essa série geométrica converge.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
