insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993009','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','easy','published','Na série $\sum_{n=0}^\infty c_n(x-7)^n$, qual número é o centro, independentemente dos coeficientes $c_n$?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
