insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930091','40000000-0000-4000-8000-000000993009','Compare a potência com a forma padrão $(x-a)^n$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930092','40000000-0000-4000-8000-000000993009','O centro é o valor de $x$ que zera o fator elevado a $n$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930093','40000000-0000-4000-8000-000000993009','Os coeficientes influenciam a convergência, mas não mudam esse ponto de referência.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993009','$7$','A forma padrão de uma série de potências centrada em $a$ é $\sum c_n(x-a)^n$. Aqui o fator é $x-7$. Portanto $a=7$. Substituindo $x=7$, todas as potências de ordem positiva se anulam, como esperado no centro. A alternativa C identifica corretamente esse valor.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930091','40000000-0000-4000-8000-000000993009','A forma padrão de uma série de potências centrada em $a$ é $\sum c_n(x-a)^n$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930092','40000000-0000-4000-8000-000000993009','Aqui o fator é $x-7$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
