insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993010','$1-x+x^2/2-x^3/6$','A expansão é $e^u=1+u+u^2/2!+u^3/3!+\cdots$. Substituindo $u=-x$, obtemos $1-x+(-x)^2/2+(-x)^3/6$. Simplificando os sinais, resulta $1-x+x^2/2-x^3/6$. O grau $3$ exige parar no termo cúbico. A alternativa A tem sinais e fatoriais corretos.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930101','40000000-0000-4000-8000-000000993010','A expansão é $e^u=1+u+u^2/2!+u^3/3!+\cdots$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930102','40000000-0000-4000-8000-000000993010','Substituindo $u=-x$, obtemos $1-x+(-x)^2/2+(-x)^3/6$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
