insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930112','40000000-0000-4000-8000-000000993011','Integre $2t+3$ de $0$ a $2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
