insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993011','$10$ L','A entrada total é $\int_0^2(2t+3)\,dt$. Uma primitiva é $t^2+3t$. No instante $2$, o valor acumulado é $4+6=10$. No instante inicial, a primitiva vale zero. Portanto entram $10$ litros, alternativa C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930111','40000000-0000-4000-8000-000000993011','A entrada total é $\int_0^2(2t+3)\,dt$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
