insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930113','40000000-0000-4000-8000-000000993011','No instante $2$, o valor acumulado é $4+6=10$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930114','40000000-0000-4000-8000-000000993011','No instante inicial, a primitiva vale zero.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930115','40000000-0000-4000-8000-000000993011','Portanto entram $10$ litros, alternativa C.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993012','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','medium','published','Ao planejar $\int x^2e^x\,dx$, quantas aplicações sucessivas de integração por partes reduzem o problema a uma integral imediata?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
