insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930121','40000000-0000-4000-8000-000000993012','Observe como o grau do fator polinomial muda quando ele é derivado.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930122','40000000-0000-4000-8000-000000993012','Escolher $u=x^2$ produz primeiro um termo com $\int xe^x\,dx$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930123','40000000-0000-4000-8000-000000993012','Uma segunda derivação do fator polinomial deixa apenas $\int e^x\,dx$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993012','Duas','O fator exponencial permanece simples ao ser integrado, enquanto $x^2$ reduz o grau ao ser derivado. Na primeira aplicação, com $u=x^2$, a integral residual é proporcional a $\int xe^x\,dx$. Essa integral ainda é um produto e pede nova aplicação por partes. Na segunda aplicação, derivar $x$ produz $1$, deixando $\int e^x\,dx$, que é imediata. Portanto são necessárias duas aplicações, alternativa C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930121','40000000-0000-4000-8000-000000993012','O fator exponencial permanece simples ao ser integrado, enquanto $x^2$ reduz o grau ao ser derivado.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930122','40000000-0000-4000-8000-000000993012','Na primeira aplicação, com $u=x^2$, a integral residual é proporcional a $\int xe^x\,dx$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930123','40000000-0000-4000-8000-000000993012','Essa integral ainda é um produto e pede nova aplicação por partes.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930124','40000000-0000-4000-8000-000000993012','Na segunda aplicação, derivar $x$ produz $1$, deixando $\int e^x\,dx$, que é imediata.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930125','40000000-0000-4000-8000-000000993012','Portanto são necessárias duas aplicações, alternativa C.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
