insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930132','40000000-0000-4000-8000-000000993013','B','$\frac{A}{x+1}+\frac{B}{(x+1)^2}$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
