insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930131','40000000-0000-4000-8000-000000993013','Um fator linear repetido exige uma parcela para cada potência até sua multiplicidade.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930132','40000000-0000-4000-8000-000000993013','Liste os denominadores $x+1$ e $(x+1)^2$ separadamente.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930133','40000000-0000-4000-8000-000000993013','Os numeradores sobre fatores lineares são constantes.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993013','$\frac{A}{x+1}+\frac{B}{(x+1)^2}$','O denominador possui apenas o fator linear $x+1$, repetido duas vezes. Para multiplicidade dois, a decomposição completa inclui as potências primeira e segunda. Cada numerador deve ter grau menor que o fator linear, portanto é constante. A forma correta é $A/(x+1)+B/(x+1)^2$. A alternativa B inclui todas e somente as parcelas necessárias.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930131','40000000-0000-4000-8000-000000993013','O denominador possui apenas o fator linear $x+1$, repetido duas vezes.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930132','40000000-0000-4000-8000-000000993013','Para multiplicidade dois, a decomposição completa inclui as potências primeira e segunda.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930133','40000000-0000-4000-8000-000000993013','Cada numerador deve ter grau menor que o fator linear, portanto é constante.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930134','40000000-0000-4000-8000-000000993013','A forma correta é $A/(x+1)+B/(x+1)^2$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
