insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930141','40000000-0000-4000-8000-000000993014','As duas potências trigonométricas são pares.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930142','40000000-0000-4000-8000-000000993014','Quando não há potência ímpar para separar, as identidades de meio ângulo são naturais.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930143','40000000-0000-4000-8000-000000993014','A substituição simples deixaria uma raiz ao reescrever o fator restante.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993014','Aplicar identidades de redução de potência aos dois fatores','O integrando contém potências pares tanto de seno quanto de cosseno. Não é possível reservar um único fator cuja potência remanescente se converta polinomialmente sem raiz. Usamos $\sin^2x=(1-\cos2x)/2$ e $\cos^2x=(1+\cos2x)/2$. Depois dessas identidades, produtos de cossenos podem ser novamente reduzidos e integrados termo a termo. Logo a estratégia indicada na alternativa C é a mais eficiente.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930141','40000000-0000-4000-8000-000000993014','O integrando contém potências pares tanto de seno quanto de cosseno.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
