insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930143','40000000-0000-4000-8000-000000993014','Usamos $\sin^2x=(1-\cos2x)/2$ e $\cos^2x=(1+\cos2x)/2$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
