insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993015','Nenhuma; as duas propriedades já bastam','O enunciado fornece monotonicidade crescente. Também fornece uma cota superior para todos os termos. O teorema da convergência monótona afirma que uma sequência crescente e limitada acima converge. Não é necessário conhecer previamente o limite nem ter termos inteiros ou razão constante. Assim, a alternativa A é a conclusão lógica correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
