insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930161','40000000-0000-4000-8000-000000993016','Para provar convergência, procure uma série convergente que fique acima dos termos dados.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930162','40000000-0000-4000-8000-000000993016','Mostre que $n^2-1\ge n^2/2$ quando $n\ge2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930163','40000000-0000-4000-8000-000000993016','Inverter números positivos troca a direção da comparação entre os denominadores.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993016','$\frac1{n^2-1}\le\frac2{n^2}$ para $n\ge2$','Para $n\ge2$, temos $n^2\ge2$, logo $n^2-1\ge n^2/2$. Como os denominadores são positivos, segue $1/(n^2-1)\le2/n^2$. A série $\sum2/n^2$ converge por ser múltipla de uma p-série com $p=2$. A alternativa A tem a desigualdade invertida em tamanho, pois $n^2-1<n^2$. Portanto a comparação útil é a da alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930161','40000000-0000-4000-8000-000000993016','Para $n\ge2$, temos $n^2\ge2$, logo $n^2-1\ge n^2/2$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930162','40000000-0000-4000-8000-000000993016','Como os denominadores são positivos, segue $1/(n^2-1)\le2/n^2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930163','40000000-0000-4000-8000-000000993016','A série $\sum2/n^2$ converge por ser múltipla de uma p-série com $p=2$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930164','40000000-0000-4000-8000-000000993016','A alternativa A tem a desigualdade invertida em tamanho, pois $n^2-1<n^2$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930165','40000000-0000-4000-8000-000000993016','Portanto a comparação útil é a da alternativa B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993017','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','medium','published','Ao aproximar a soma de $\sum_{n=1}^\infty(-1)^{n+1}/n^3$ pelos quatro primeiros termos, qual é uma garantia para o erro absoluto?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
