insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930171','40000000-0000-4000-8000-000000993017','Para séries alternadas que satisfazem as hipóteses, o erro é limitado pelo primeiro termo omitido.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930172','40000000-0000-4000-8000-000000993017','Quatro termos foram usados, então observe o termo de índice $5$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930173','40000000-0000-4000-8000-000000993017','A estimativa usa o módulo, sem o sinal alternado.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993017','Menor ou igual a $1/125$','Os módulos $1/n^3$ diminuem e tendem a zero, portanto vale a estimativa do resto alternado. Depois de quatro parcelas, o primeiro termo não incluído tem índice $5$. Seu módulo é $1/5^3$. Assim, o erro absoluto não excede $1/125$. Essa garantia aparece na alternativa C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930171','40000000-0000-4000-8000-000000993017','Os módulos $1/n^3$ diminuem e tendem a zero, portanto vale a estimativa do resto alternado.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930172','40000000-0000-4000-8000-000000993017','Depois de quatro parcelas, o primeiro termo não incluído tem índice $5$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930173','40000000-0000-4000-8000-000000993017','Seu módulo é $1/5^3$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930174','40000000-0000-4000-8000-000000993017','Assim, o erro absoluto não excede $1/125$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
