insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993018','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','medium','published','Avalie a integral imprópria $\int_0^1\frac{\ln x}{\sqrt x}\,dx$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
