insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930181','40000000-0000-4000-8000-000000993018','A','$-4$',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930182','40000000-0000-4000-8000-000000993018','B','$-2$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930183','40000000-0000-4000-8000-000000993018','C','$0$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930184','40000000-0000-4000-8000-000000993018','D','A integral diverge',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('40000000-0000-4000-8000-000000993018','50000000-0000-4000-8000-000009930181') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930181','40000000-0000-4000-8000-000000993018','A singularidade está no extremo zero, onde é preciso combinar a potência com o logaritmo.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930182','40000000-0000-4000-8000-000000993018','Faça $x=u^2$ para eliminar simultaneamente a raiz e o diferencial.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930183','40000000-0000-4000-8000-000000993018','Depois da troca, use que $u\ln u\to0$ quando $u\to0^+$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993018','$-4$','Definimos a integral por um limite no extremo $x=0$. Com $x=u^2$, temos $dx=2u\,du$, $\sqrt x=u$ e $\ln x=2\ln u$. O integrando transformado é $4\ln u\,du$, com limites de $0$ a $1$. Como $\int_0^1\ln u\,du=-1$, o valor procurado é $4(-1)=-4$. A troca também confirma a convergência da singularidade; a resposta é A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930181','40000000-0000-4000-8000-000000993018','Definimos a integral por um limite no extremo $x=0$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930182','40000000-0000-4000-8000-000000993018','Com $x=u^2$, temos $dx=2u\,du$, $\sqrt x=u$ e $\ln x=2\ln u$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930183','40000000-0000-4000-8000-000000993018','O integrando transformado é $4\ln u\,du$, com limites de $0$ a $1$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930184','40000000-0000-4000-8000-000000993018','Como $\int_0^1\ln u\,du=-1$, o valor procurado é $4(-1)=-4$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930185','40000000-0000-4000-8000-000000993018','A troca também confirma a convergência da singularidade; a resposta é A.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993019','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','medium','published','A série $\sum_{n=1}^\infty\frac{(x-2)^n}{n5^n}$ converge em $x=-3$?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
