insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930191','40000000-0000-4000-8000-000000993019','Substitua o valor do extremo antes de classificar.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930192','40000000-0000-4000-8000-000000993019','Em $x=-3$, a potência contribui com um fator $(-5)^n$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930193','40000000-0000-4000-8000-000000993019','Compare a série obtida com a harmônica alternada e com sua versão absoluta.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993019','Sim, condicionalmente','Em $x=-3$, temos $(x-2)^n=(-5)^n$. Dividindo por $5^n$, o termo torna-se $(-1)^n/n$. A série harmônica alternada converge pelo teste alternado. A série dos módulos é $\sum1/n$, que diverge. Portanto a convergência é condicional, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930191','40000000-0000-4000-8000-000000993019','Em $x=-3$, temos $(x-2)^n=(-5)^n$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
