insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993020','$1-(x-1)+(x-1)^2$','Para $f(x)=x^{-1}$, temos $f(1)=1$. A primeira derivada é $-x^{-2}$, logo $f\prime(1)=-1$. A segunda derivada é $2x^{-3}$, então $f\prime\prime(1)/2!=1$. Substituindo na fórmula, $P_2(x)=1-(x-1)+(x-1)^2$. A alternativa A respeita o centro e os três coeficientes.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930201','40000000-0000-4000-8000-000000993020','Para $f(x)=x^{-1}$, temos $f(1)=1$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930202','40000000-0000-4000-8000-000000993020','A primeira derivada é $-x^{-2}$, logo $f\prime(1)=-1$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930203','40000000-0000-4000-8000-000000993020','A segunda derivada é $2x^{-3}$, então $f\prime\prime(1)/2!=1$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930204','40000000-0000-4000-8000-000000993020','Substituindo na fórmula, $P_2(x)=1-(x-1)+(x-1)^2$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
