insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930211','40000000-0000-4000-8000-000000993021','Primeiro encontre as interseções de $x^2$ e $2-x$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930212','40000000-0000-4000-8000-000000993021','Ao girar em torno do eixo $x$, os raios são valores de $y$, e entram ao quadrado.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930213','40000000-0000-4000-8000-000000993021','O raio externo é dado pela curva superior entre $x=-2$ e $x=1$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993021','$\pi\int_{-2}^{1}[(2-x)^2-x^4]dx$','As interseções resolvem $x^2=2-x$, isto é, $(x+2)(x-1)=0$. No intervalo $[-2,1]$, a reta $2-x$ fica acima da parábola $x^2$. Ao redor do eixo $x$, o raio externo é $R=2-x$ e o interno é $r=x^2$. A área da seção é $\pi(R^2-r^2)=\pi[(2-x)^2-x^4]$. Integrando de $-2$ a $1$, obtemos exatamente a alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930211','40000000-0000-4000-8000-000000993021','As interseções resolvem $x^2=2-x$, isto é, $(x+2)(x-1)=0$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930212','40000000-0000-4000-8000-000000993021','No intervalo $[-2,1]$, a reta $2-x$ fica acima da parábola $x^2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930213','40000000-0000-4000-8000-000000993021','Ao redor do eixo $x$, o raio externo é $R=2-x$ e o interno é $r=x^2$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930214','40000000-0000-4000-8000-000000993021','A área da seção é $\pi(R^2-r^2)=\pi[(2-x)^2-x^4]$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930215','40000000-0000-4000-8000-000000993021','Integrando de $-2$ a $1$, obtemos exatamente a alternativa A.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993022','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','medium','published','Uma força variável $F(x)=4x+1$ newtons move um objeto de $x=0$ a $x=3$ metros. Qual trabalho é realizado?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
