insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993022','$21$ J','Modelamos o trabalho por $W=\int_0^3(4x+1)dx$. A antiderivada é $2x^2+x$. No extremo final, ela vale $2\cdot9+3=21$. No extremo inicial, o valor é zero. Logo o trabalho é $21$ joules, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
