insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930233','40000000-0000-4000-8000-000000993023','Confira os sinais de $\sin\pi$, $\cos\pi$ e $\cos0$ somente após obter a primitiva.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993023','$-(e^\pi+1)/2$','Denote por $I=\int e^x\cos xdx$ e aplique partes com $u=\cos x$ e $dv=e^xdx$. Isso dá $I=e^x\cos x+\int e^x\sin xdx$. Aplicando partes à integral restante, obtemos $\int e^x\sin xdx=e^x\sin x-I$. Logo $2I=e^x(\sin x+\cos x)$ e uma primitiva é $e^x(\sin x+\cos x)/2$. A avaliação de $0$ a $\pi$ produz $-e^\pi/2-1/2=-(e^\pi+1)/2$, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930231','40000000-0000-4000-8000-000000993023','Denote por $I=\int e^x\cos xdx$ e aplique partes com $u=\cos x$ e $dv=e^xdx$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930232','40000000-0000-4000-8000-000000993023','Isso dá $I=e^x\cos x+\int e^x\sin xdx$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930233','40000000-0000-4000-8000-000000993023','Aplicando partes à integral restante, obtemos $\int e^x\sin xdx=e^x\sin x-I$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930234','40000000-0000-4000-8000-000000993023','Logo $2I=e^x(\sin x+\cos x)$ e uma primitiva é $e^x(\sin x+\cos x)/2$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
