insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930242','40000000-0000-4000-8000-000000993024','O fator linear $x$ aparece ao quadrado, então exige parcelas para $x$ e $x^2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930243','40000000-0000-4000-8000-000000993024','Sobre o quadrático irredutível, o numerador precisa ter grau menor que dois.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993024','$\frac A{x}+\frac B{x^2}+\frac{Cx+D}{x^2+1}$','O denominador já está fatorado como $x^2(x^2+1)$. Para o fator linear repetido $x^2$, entram $A/x$ e $B/x^2$. O fator $x^2+1$ é quadrático irredutível nos reais. Seu numerador geral deve ser linear, $Cx+D$. Somando essas exigências, obtemos exatamente a forma da alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930241','40000000-0000-4000-8000-000000993024','O denominador já está fatorado como $x^2(x^2+1)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
