insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930252','40000000-0000-4000-8000-000000993025','B','$\frac{5\sqrt2}{8}+\frac38\ln(1+\sqrt2)$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
