insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930251','40000000-0000-4000-8000-000000993025','A integral de potência ímpar de secante pode ser reduzida por partes reservando $\sec^3x\cdot\sec^2x$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930252','40000000-0000-4000-8000-000000993025','Use $\tan^2x=\sec^2x-1$ para fazer a integral original reaparecer.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930253','40000000-0000-4000-8000-000000993025','Na avaliação final, $\sec(\pi/4)=\sqrt2$ e $\tan(\pi/4)=1$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993025','$\frac{7\sqrt2}{8}+\frac38\ln(1+\sqrt2)$','Escreva $I_5=\int\sec^3x\,\sec^2x\,dx$ e aplique partes com $u=\sec^3x$ e $dv=\sec^2x dx$. Temos $du=3\sec^3x\tan xdx$ e $v=\tan x$, logo $I_5=\sec^3x\tan x-3\int\sec^3x\tan^2x dx$. Substituindo $\tan^2x=\sec^2x-1$, resulta $4I_5=\sec^3x\tan x+3I_3$. Como $I_3=(\sec x\tan x+\ln|\sec x+\tan x|)/2$, obtemos $I_5=\sec^3x\tan x/4+3\sec x\tan x/8+3\ln|\sec x+\tan x|/8$. A primitiva vale zero em $0$ e, em $\pi/4$, vale $7\sqrt2/8+3\ln(1+\sqrt2)/8$, alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930251','40000000-0000-4000-8000-000000993025','Escreva $I_5=\int\sec^3x\,\sec^2x\,dx$ e aplique partes com $u=\sec^3x$ e $dv=\sec^2x dx$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930252','40000000-0000-4000-8000-000000993025','Temos $du=3\sec^3x\tan xdx$ e $v=\tan x$, logo $I_5=\sec^3x\tan x-3\int\sec^3x\tan^2x dx$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930253','40000000-0000-4000-8000-000000993025','Substituindo $\tan^2x=\sec^2x-1$, resulta $4I_5=\sec^3x\tan x+3I_3$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930254','40000000-0000-4000-8000-000000993025','Como $I_3=(\sec x\tan x+\ln|\sec x+\tan x|)/2$, obtemos $I_5=\sec^3x\tan x/4+3\sec x\tan x/8+3\ln|\sec x+\tan x|/8$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930255','40000000-0000-4000-8000-000000993025','A primitiva vale zero em $0$ e, em $\pi/4$, vale $7\sqrt2/8+3\ln(1+\sqrt2)/8$, alternativa A.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993026','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','hard','published','Para quais pares reais $(a,b)$ a integral $\int_0^\infty\frac{x^a}{(1+x)^b}\,dx$ converge?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('40000000-0000-4000-8000-000000993026','30000000-0000-4000-8000-000000000105',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930261','40000000-0000-4000-8000-000000993026','A','$a>0$ e $b>a$',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930262','40000000-0000-4000-8000-000000993026','B','$a>-1$ e $b>a+1$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930263','40000000-0000-4000-8000-000000993026','C','$a<1$ e $b>a-1$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930264','40000000-0000-4000-8000-000000993026','D','$a\ge-1$ e $b\ge a+1$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
