insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930261','40000000-0000-4000-8000-000000993026','Há dois comportamentos impróprios independentes: perto de zero e no infinito.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930262','40000000-0000-4000-8000-000000993026','Perto de zero, compare com $x^a$; para $x$ grande, compare com $x^{a-b}$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930263','40000000-0000-4000-8000-000000993026','Os casos de igualdade nos expoentes geram integrais logarítmicas divergentes.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993026','$a>-1$ e $b>a+1$','Quando $x\to0^+$, $(1+x)^b$ tende a $1$, então o integrando se comporta como $x^a$. A integral $\int_0^1x^a dx$ converge exatamente para $a>-1$. Quando $x\to\infty$, o quociente se comporta como $x^{a-b}$. A integral no infinito converge quando $a-b<-1$, isto é, $b>a+1$. As duas condições devem valer simultaneamente, produzindo a alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930261','40000000-0000-4000-8000-000000993026','Quando $x\to0^+$, $(1+x)^b$ tende a $1$, então o integrando se comporta como $x^a$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930262','40000000-0000-4000-8000-000000993026','A integral $\int_0^1x^a dx$ converge exatamente para $a>-1$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930263','40000000-0000-4000-8000-000000993026','Quando $x\to\infty$, o quociente se comporta como $x^{a-b}$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930264','40000000-0000-4000-8000-000000993026','A integral no infinito converge quando $a-b<-1$, isto é, $b>a+1$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
