insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930272','40000000-0000-4000-8000-000000993027','Ao extrair a raiz $n$-ésima, resta $(n/(n+1))^n$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930273','40000000-0000-4000-8000-000000993027','Reconheça o limite recíproco de $(1+1/n)^n$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993027','Converge pelo teste da raiz','Defina $a_n=(n/(n+1))^{n^2}$, que é positivo. O teste da raiz considera $\sqrt[n]{a_n}=(n/(n+1))^n$. Reescrevemos essa expressão como $(1+1/n)^{-n}$. Seu limite é $e^{-1}$, estritamente menor que $1$. Logo a série converge absolutamente pelo teste da raiz, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930271','40000000-0000-4000-8000-000000993027','Defina $a_n=(n/(n+1))^{n^2}$, que é positivo.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930272','40000000-0000-4000-8000-000000993027','O teste da raiz considera $\sqrt[n]{a_n}=(n/(n+1))^n$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
