insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930281','40000000-0000-4000-8000-000000993028','Uma comparação direta evidente não aparece; examine a expansão local de $\sin x$ em zero.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930282','40000000-0000-4000-8000-000000993028','Substitua $x=1/n$ até o primeiro termo que não cancela com $1/n$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930283','40000000-0000-4000-8000-000000993028','Para convergência absoluta, compare o módulo do resto dominante com uma p-série.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993028','Convergente absolutamente, pois o termo dominante é da ordem de $1/n^3$','A expansão em zero é $\sin x=x-x^3/6+O(x^5)$. Com $x=1/n$, temos $\sin(1/n)=1/n-1/(6n^3)+O(1/n^5)$. Subtraindo $1/n$, o termo da série é $-1/(6n^3)+O(1/n^5)$. Seu módulo é assintoticamente comparável a $1/(6n^3)$, cuja série converge. Portanto há convergência absoluta, como afirma a alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930281','40000000-0000-4000-8000-000000993028','A expansão em zero é $\sin x=x-x^3/6+O(x^5)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930282','40000000-0000-4000-8000-000000993028','Com $x=1/n$, temos $\sin(1/n)=1/n-1/(6n^3)+O(1/n^5)$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930283','40000000-0000-4000-8000-000000993028','Subtraindo $1/n$, o termo da série é $-1/(6n^3)+O(1/n^5)$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930284','40000000-0000-4000-8000-000000993028','Seu módulo é assintoticamente comparável a $1/(6n^3)$, cuja série converge.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930285','40000000-0000-4000-8000-000000993028','Portanto há convergência absoluta, como afirma a alternativa B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993029','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','hard','published','Classifique $\sum_{n=2}^\infty(-1)^n\frac{\ln n}{n}$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
