insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930291','40000000-0000-4000-8000-000000993029','O teste alternado exige apenas monotonicidade eventual, não necessariamente desde o primeiro índice.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930292','40000000-0000-4000-8000-000000993029','Estude a derivada de $\ln x/x$ para localizar quando os módulos passam a decrescer.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930293','40000000-0000-4000-8000-000000993029','Para a série absoluta, use o teste da integral com a substituição $u=\ln x$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993029','Converge condicionalmente','A função $f(x)=\ln x/x$ tende a zero quando $x\to\infty$. Sua derivada é $(1-\ln x)/x^2$, negativa para $x>e$, portanto os termos são eventualmente decrescentes. O teste alternado garante convergência da série com sinais. Para os módulos, $\int_2^\infty\ln x/x\,dx=[(\ln x)^2/2]_2^\infty$ diverge. Assim a convergência é condicional, alternativa C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930291','40000000-0000-4000-8000-000000993029','A função $f(x)=\ln x/x$ tende a zero quando $x\to\infty$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930292','40000000-0000-4000-8000-000000993029','Sua derivada é $(1-\ln x)/x^2$, negativa para $x>e$, portanto os termos são eventualmente decrescentes.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930293','40000000-0000-4000-8000-000000993029','O teste alternado garante convergência da série com sinais.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930294','40000000-0000-4000-8000-000000993029','Para os módulos, $\int_2^\infty\ln x/x\,dx=[(\ln x)^2/2]_2^\infty$ diverge.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930295','40000000-0000-4000-8000-000000993029','Assim a convergência é condicional, alternativa C.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993030','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','hard','published','Determine o intervalo de convergência de $\sum_{n=2}^\infty\frac{(-1)^n(x-2)^n}{n\,4^n}$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
