insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930301','40000000-0000-4000-8000-000000993030','Encontre primeiro o raio a partir do fator $4^n$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930302','40000000-0000-4000-8000-000000993030','Em $x=6$, o sinal $(-1)^n$ permanece; em $x=-2$, ele é cancelado por outra potência negativa.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930303','40000000-0000-4000-8000-000000993030','Decida cada extremo distinguindo a harmônica da harmônica alternada.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993030','$(-2,6]$','O teste da razão fornece $|x-2|<4$, isto é, o intervalo aberto $(-2,6)$. No extremo $x=6$, o termo se reduz a $(-1)^n/n$, e a série converge pelo teste alternado. No extremo $x=-2$, temos $(-1)^n(-4)^n/(n4^n)=1/n$. A série harmônica diverge nesse extremo. Incluímos apenas $6$, obtendo $(-2,6]$, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930301','40000000-0000-4000-8000-000000993030','O teste da razão fornece $|x-2|<4$, isto é, o intervalo aberto $(-2,6)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930302','40000000-0000-4000-8000-000000993030','No extremo $x=6$, o termo se reduz a $(-1)^n/n$, e a série converge pelo teste alternado.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930303','40000000-0000-4000-8000-000000993030','No extremo $x=-2$, temos $(-1)^n(-4)^n/(n4^n)=1/n$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930304','40000000-0000-4000-8000-000000993030','A série harmônica diverge nesse extremo.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
