insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993031','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','hard','published','Usando Taylor, qual é o menor grau entre as opções que garante erro inferior a $10^{-4}$ ao aproximar $e^{0,2}$ por Maclaurin? Considere a estimativa $|R_n(0,2)|\le e^{0,2}0,2^{n+1}/(n+1)!$ e use $e^{0,2}<1,23$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
