insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930311','40000000-0000-4000-8000-000000993031','A estimativa já fornece um majorante; teste os graus em ordem crescente.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930312','40000000-0000-4000-8000-000000993031','Para grau $3$, avalie $1,23\cdot0,2^4/4!$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930313','40000000-0000-4000-8000-000000993031','Compare também com o majorante de grau $2$ para justificar que o grau escolhido é o menor.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993031','Grau $3$','Para grau $3$, o majorante é $1,23\cdot0,2^4/4!=1,23\cdot0,0016/24\approx0,000082$. Esse valor já é menor que $10^{-4}$. Para grau $2$, o majorante seria $1,23\cdot0,2^3/3!=1,23\cdot0,008/6\approx0,00164$, maior que a tolerância. Logo o menor grau suficiente é $3$. Portanto a alternativa correta é B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930311','40000000-0000-4000-8000-000000993031','Para grau $3$, o majorante é $1,23\cdot0,2^4/4!=1,23\cdot0,0016/24\approx0,000082$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930312','40000000-0000-4000-8000-000000993031','Esse valor já é menor que $10^{-4}$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930313','40000000-0000-4000-8000-000000993031','Para grau $2$, o majorante seria $1,23\cdot0,2^3/3!=1,23\cdot0,008/6\approx0,00164$, maior que a tolerância.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
