insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930321','40000000-0000-4000-8000-000000993032','A função é ímpar, mas a área não é a integral assinada; use a simetria dos módulos.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930322','40000000-0000-4000-8000-000000993032','No semieixo positivo, o sinal muda em $x=1$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930323','40000000-0000-4000-8000-000000993032','Some as integrais positivas em $[0,1]$ e $[1,2]$ antes de dobrar.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993032','$5$','A função $x^3-x=x(x-1)(x+1)$ zera em $-1$, $0$ e $1$. Como ela é ímpar, $|x^3-x|$ é par e a área total é duas vezes a área em $[0,2]$. Em $[0,1]$, usamos $x-x^3$; sua integral vale $1/2-1/4=1/4$. Em $[1,2]$, usamos $x^3-x$; a integral vale $[x^4/4-x^2/2]_1^2=9/4$. Dobrar $1/4+9/4=5/2$ fornece área $5$, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930321','40000000-0000-4000-8000-000000993032','A função $x^3-x=x(x-1)(x+1)$ zera em $-1$, $0$ e $1$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930322','40000000-0000-4000-8000-000000993032','Como ela é ímpar, $|x^3-x|$ é par e a área total é duas vezes a área em $[0,2]$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930323','40000000-0000-4000-8000-000000993032','Em $[0,1]$, usamos $x-x^3$; sua integral vale $1/2-1/4=1/4$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930324','40000000-0000-4000-8000-000000993032','Em $[1,2]$, usamos $x^3-x$; a integral vale $[x^4/4-x^2/2]_1^2=9/4$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930325','40000000-0000-4000-8000-000000993032','Dobrar $1/4+9/4=5/2$ fornece área $5$, alternativa B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993033','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','medium','published','A região $R$ é limitada por $y=x^2$, $y=4$ e $x=0$, no primeiro quadrante. Ao girar $R$ em torno da reta vertical $x=3$, qual integral pelo método das cascas cilíndricas representa o volume?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('40000000-0000-4000-8000-000000993033','30000000-0000-4000-8000-000000000004',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
