insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930331','40000000-0000-4000-8000-000000993033','Cascas em torno de um eixo vertical usam tiras verticais.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930332','40000000-0000-4000-8000-000000993033','O raio é a distância horizontal de $x$ até a reta $x=3$, e não a distância até o eixo $y$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930333','40000000-0000-4000-8000-000000993033','A altura da casca é curva superior menos curva inferior.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993033','$2\pi\int_0^2(3-x)(4-x^2)dx$','As fronteiras $y=x^2$ e $y=4$ se encontram no primeiro quadrante em $x=2$. Uma tira vertical percorre $0\le x\le2$ e tem altura $4-x^2$. Ao girar em torno de $x=3$, o raio da casca é $3-x$. O elemento de volume é $2\pi(3-x)(4-x^2)dx$. Integrando de $0$ a $2$, obtemos a montagem da alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930331','40000000-0000-4000-8000-000000993033','As fronteiras $y=x^2$ e $y=4$ se encontram no primeiro quadrante em $x=2$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930332','40000000-0000-4000-8000-000000993033','Uma tira vertical percorre $0\le x\le2$ e tem altura $4-x^2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930333','40000000-0000-4000-8000-000000993033','Ao girar em torno de $x=3$, o raio da casca é $3-x$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930334','40000000-0000-4000-8000-000000993033','O elemento de volume é $2\pi(3-x)(4-x^2)dx$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930335','40000000-0000-4000-8000-000000993033','Integrando de $0$ a $2$, obtemos a montagem da alternativa B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000993034','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009903','multiple_choice','hard','published','Partindo da série geométrica e de suas derivadas, determine a soma exata de $\sum_{n=1}^\infty n^2/2^n$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('40000000-0000-4000-8000-000000993034','30000000-0000-4000-8000-000000000112',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930341','40000000-0000-4000-8000-000000993034','A','$2$',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930342','40000000-0000-4000-8000-000000993034','B','$4$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930343','40000000-0000-4000-8000-000000993034','C','$6$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000009930344','40000000-0000-4000-8000-000000993034','D','$8$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('40000000-0000-4000-8000-000000993034','50000000-0000-4000-8000-000009930343') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930341','40000000-0000-4000-8000-000000993034','Diferenciar uma vez $\sum_{n=0}^\infty x^n=1/(1-x)$ produz uma série com o fator $n$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930342','40000000-0000-4000-8000-000000993034','Para obter $n^2$, combine $n(n-1)$, vindo da segunda derivada, com o fator $n$ da primeira.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000009930343','40000000-0000-4000-8000-000000993034','Construa primeiro $\sum n^2x^n=x(1+x)/(1-x)^3$ e somente depois use $x=1/2$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000993034','$6$','Para $|x|<1$, a série geométrica satisfaz $G(x)=\sum_{n=0}^\infty x^n=1/(1-x)$. Multiplicando a primeira derivada por $x$, obtemos $\sum_{n=1}^\infty nx^n=x/(1-x)^2$. Derivar essa última série e multiplicar novamente por $x$ transforma o lado esquerdo em $\sum_{n=1}^\infty n^2x^n$. No lado direito, o cálculo fornece $x(1+x)/(1-x)^3$; em $x=1/2$, isso vale $(1/2)(3/2)/(1/2)^3=6$. Como $|1/2|<1$, as diferenciações são válidas dentro do raio de convergência, e a alternativa correta é C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930341','40000000-0000-4000-8000-000000993034','Para $|x|<1$, a série geométrica satisfaz $G(x)=\sum_{n=0}^\infty x^n=1/(1-x)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930342','40000000-0000-4000-8000-000000993034','Multiplicando a primeira derivada por $x$, obtemos $\sum_{n=1}^\infty nx^n=x/(1-x)^2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930343','40000000-0000-4000-8000-000000993034','Derivar essa última série e multiplicar novamente por $x$ transforma o lado esquerdo em $\sum_{n=1}^\infty n^2x^n$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930344','40000000-0000-4000-8000-000000993034','No lado direito, o cálculo fornece $x(1+x)/(1-x)^3$; em $x=1/2$, isso vale $(1/2)(3/2)/(1/2)^3=6$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000009930345','40000000-0000-4000-8000-000000993034','Como $|1/2|<1$, as diferenciações são válidas dentro do raio de convergência, e a alternativa correta é C.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
